function o(e){const i=(e.blocks||[]).filter(t=>t.kind!=="break"),n=i.filter(t=>t.kind==="homework"),s=i.filter(t=>t.kind!=="homework");return{blocks:n.concat(s).map(t=>({id:String(t.id),subject:t.subject??null,kind:t.kind||"study",title:t.title||"Study",minutes:Math.max(5,Math.round((+t.minutes||30)/5)*5),why:t.kind==="homework"?"Simulated tip: finish what is due soonest first.":"Simulated tip: start with the question you find hardest."}))}}export{o as default};
